/* Operación diaria exclusivamente: estado, folios, tabla y calendario. */
(()=>{'use strict';
const acronyms={'SANTA ANA_A':'SAN','SANTA ANA':'SAN','PATRIA':'PAT','PATRIA_2_A':'PAT','PATRIA_A':'PAT','PATRIA_4_A':'PAT','AMPLIACION PATRIA 2':'PAT','AMPLIACION PATRIA 3':'PAT','AMPLIACIÓN PATRIA 4':'PAT','AMPLIACION PATRIA 5':'PAT','VALLARTA':'VALL','VALLARTA_A':'VALL','AMPLIACION SANTA ANA II':'SNT','AMPLIACION SANTA ANA II_2':'SNT','AMPLIACIÓN SANTA ANA II_3':'SNT','SANTA ANA II':'SNT','SANTA_ANA_II_A':'SNT','AMPLIACION SOLARES 2':'SOL','AMPLIACION SOLARES 2_A':'SOL','AMPLIACION SOLARES 2_2_A':'SOL','AMPLIACION SOLARES 2_3_A':'SOL','AMPLIACION SOLARES 2_5_A':'SOL','SOLARES':'SOL'};
let state={records:[],pauses:[],coverage:[],counter:0},db,ready=false,dates=null,draft=new Set(),month=new Date().getMonth(),year=new Date().getFullYear(),pending=null;const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();
const duration=n=>{if(!Number.isFinite(n)||n<0)return '—';n=Math.floor(n/1000);return String(Math.floor(n/3600)).padStart(2,'0')+':'+String(Math.floor(n/60)%60).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};
const tds=r=>r.end&&r.start?duration(new Date(r.end)-new Date(r.start)):'—';
const slaHours={'ATENUADO':6,'ATENUADO RETORNO':6,'BY PASS':48,'PIGTAIL DAÑADO':12,'SATURADO':12,'SIN POTENCIA':12};
function sla(r){const failure=String(r.failure||'').trim().toUpperCase().replace(/\s+/g,' ').replace('SATRUADO','SATURADO'),hours=slaHours[failure];if(!hours)return 'Sin SLA definido';if(!r.end||!r.start)return 'Pendiente';const elapsed=new Date(r.end)-new Date(r.start);if(!Number.isFinite(elapsed)||elapsed<0)return 'Revisar fechas';return elapsed<=hours*3600000?'DENTRO DE SLA':'FUERA DE SLA'}
const noOT=r=>!String(r.ot||'').trim()||/^(PENDIENTE|SIN\s*OT|N\/?A)$/i.test(String(r.ot).trim());
const columnFilters=new Map();
const values=r=>[r.folio||'Pendiente de clúster',r.ot||'',r.os||'',r.failure||'',r.subtype||'',r.cluster||'',(r.start||'').replace('T',' '),(r.end||'').replace('T',' '),'00:00:00',tds(r),sla(r),r.status||'',r.person||''];
function matchesColumns(r){return [...columnFilters].every(([i,f])=>{const v=String(values(r)[i]);return (!f.enabled||f.selected.has(v))&&(i!==1||!f.mode|| (f.mode==='without'?noOT(r):!noOT(r)))})}
const norm=s=>String(s||'').trim().toUpperCase().replace(/\s+/g,' ').replace('SATRUADO','SATURADO');
const failureColors={'SATURADO':'#ff690b','SIN POTENCIA':'#a55bd0','ATENUADO':'#35abb1','BY PASS':'#ffb343','PIGTAIL DAÑADO':'#e7478c','ATENUADO RETORNO':'#557cba'};
window.odFailureName=norm;window.odFailureColor=f=>failureColors[norm(f)]||'#7a8494';
function folio(r){const code=acronyms[r.cluster];if(!code)return '';return 'GDL-'+code+'-'+String(++state.counter).padStart(2,'0')}
function statuses(){const current=$('status').value;const names=[...new Set(data.map(r=>r.status).filter(Boolean))].sort();$('status').replaceChildren(new Option('Todos',''),...names.map(n=>new Option(n,n)));if(names.includes(current))$('status').value=current;}
function origin(){return data.some(r=>r.origin==='import')?'REGISTROS LOCALES · BASE IMPORTADA':data.length?'REGISTROS LOCALES · CAPTURA MANUAL':'SIN REGISTROS · CARGA UNA BASE PARA COMENZAR'}
function sync(){data.splice(0,data.length,...state.records);statuses();refreshColumnOptions();$('data-origin').textContent=origin();render()}
async function save(){if(!db)throw Error('El almacenamiento no está disponible.');state.records=[...data];const snapshot=structuredClone(state);await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('No se guardaron los datos.'))});$('storage-note').textContent='Datos guardados en este navegador. No se comparten con otros usuarios todavía.';}
async function safelySave(){try{await save()}catch(e){$('storage-note').textContent='No se pudieron guardar los cambios: '+e.message;toast('No cierres el módulo: los cambios no quedaron guardados.')}}
window.odRender=function(){if(window.odResetMapSearch)window.odResetMapSearch();const q=$('search').value.trim().toLowerCase(),status=$('status').value;visible=data.filter(r=>matchesColumns(r)&&(!status||r.status===status)&&(!dates||dates.has(String(r.start||'').slice(0,10))));$('search-x').hidden=!q;document.querySelectorAll('.kpi strong').forEach((el,i)=>el.textContent=i===0?visible.length:i===1?visible.filter(noOT).length:visible.filter(r=>r.status===['','','EN CURSO','TERMINADO','CANCELADO'][i]).length);$('rows').innerHTML=visible.length?visible.map((r,i)=>'<tr tabindex="0" data-i="'+i+'">'+[r.folio||'Pendiente de clúster',r.ot,r.os,r.failure,r.subtype,r.cluster,(r.start||'').replace('T',' '),(r.end||'').replace('T',' '),'00:00:00',tds(r),sla(r),r.status,r.person].map((v,k)=>'<td>'+(k===11?badge(v):esc(k===12?(v||''):(v||'—')))+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="13">'+(data.length?'No hay registros con estos filtros.':'No hay registros. Utiliza «Carga de registros» para comenzar.')+'</td></tr>';document.querySelectorAll('#rows tr[data-i]').forEach(tr=>{const open=()=>openDetail(visible[+tr.dataset.i]);tr.ondblclick=open;tr.onkeydown=e=>{if(e.key==='Enter')open()}});$('count').textContent=visible.length+' registros visibles de '+data.length;charts();};
function openDetail(r){selected=r;detail(r);let h=$('detail');h.querySelectorAll('p.hint').forEach(el=>{if(el.textContent.includes('Cálculo pendiente'))el.textContent='Pausa: 00:00:00 · TDS: '+tds(r)+' · SLA: '+sla(r)});const extra=document.createElement('div');extra.innerHTML='<h3>Folio</h3><p>'+esc(r.folio||'Pendiente de asignar: clúster sin acrónimo definido')+'</p><h3>Pausas históricas importadas</h3><p class="hint">Se conservan para consulta; aún no se descuentan del TDS.</p>'+state.pauses.filter(p=>r.ot&&p.ot===r.ot&&(!p.os||p.os===r.os)).map(p=>'<p class="hint">'+esc(p.start)+' → '+esc(p.end)+' · '+esc(p.status)+'</p>').join('');h.append(extra);if(!r.person){const label=document.createElement('label');label.textContent='Asignar técnico';const input=document.createElement('input');input.placeholder='Nombre del técnico';label.append(input);const button=document.createElement('button');button.textContent='Guardar técnico';button.style.marginTop='10px';button.onclick=async()=>{const name=input.value.trim();if(!name)return toast('Escribe el nombre del técnico.');r.person=name;await safelySave();render();$('detail-dialog').close();toast('Técnico asignado.');};h.append(label,button)}$('detail-dialog').showModal()}
$('detail-close').onclick=()=>$('detail-dialog').close();$('search-x').onclick=()=>{$('search').value='';render();$('search').focus()};

const headers=[...document.querySelectorAll('thead th')];
const filterLabels=headers.map(h=>h.textContent);
const filterPanel=document.createElement('div');filterPanel.id='column-filter-panel';filterPanel.hidden=true;filterPanel.setAttribute('role','dialog');filterPanel.setAttribute('aria-labelledby','column-filter-title');
filterPanel.innerHTML='<div class="filter-top"><strong id="column-filter-title"></strong><button type="button" id="column-filter-close" aria-label="Cerrar filtro">×</button></div><input id="column-filter-search" type="search" placeholder="Buscar opciones…" aria-label="Buscar opciones del filtro"><div id="column-filter-mode" class="filter-modes"></div><label class="filter-all"><input id="column-filter-all" type="checkbox">Seleccionar todos los visibles</label><div id="column-filter-options"></div><p class="hint" id="column-filter-count"></p><p class="hint">La tabla cambia al pulsar Aplicar.</p><div class="filter-actions"><button type="button" class="primary" id="column-filter-apply">Aplicar</button><button type="button" id="column-filter-cancel">Cancelar</button><button type="button" id="column-filter-clear">Quitar filtro</button></div>';
document.body.append(filterPanel);
const filterChips=document.createElement('div');filterChips.id='column-filter-chips';filterChips.setAttribute('aria-label','Filtros activos de la tabla');const tableWrap=document.querySelector('#records .tablewrap');tableWrap.parentNode.insertBefore(filterChips,tableWrap);
let editingColumn=null,filterDraft=null,filterAnchor=null,filterCatalog=[];
function columnOptions(i){return [...new Set(data.map(r=>String(values(r)[i])))].sort((a,b)=>a.localeCompare(b,'es',{numeric:true}))}
function copyFilter(f){return {enabled:!!f.enabled,selected:new Set(f.selected),mode:f.mode||''}}
function closeColumnFilter(){filterPanel.hidden=true;const anchor=filterAnchor;editingColumn=null;filterDraft=null;filterAnchor=null;if(anchor){anchor.setAttribute('aria-expanded','false');anchor.focus({preventScroll:true})}}
function positionColumnFilter(){if(filterPanel.hidden||!filterAnchor)return;const rect=filterAnchor.getBoundingClientRect(),margin=10,w=filterPanel.offsetWidth,h=filterPanel.offsetHeight;let top=rect.bottom+6;if(top+h>window.innerHeight-margin)top=Math.max(margin,rect.top-h-6);const left=Math.max(margin,Math.min(rect.left,window.innerWidth-w-margin));filterPanel.style.left=left+'px';filterPanel.style.top=Math.max(margin,Math.min(top,window.innerHeight-h-margin))+'px'}
function visibleOptions(){const q=$('column-filter-search').value.trim().toLocaleLowerCase();return filterCatalog.filter(v=>!q||v.toLocaleLowerCase().includes(q))}
function paintColumnChoices(){const list=$('column-filter-options');list.replaceChildren();const options=visibleOptions();for(const v of options){const label=document.createElement('label'),check=document.createElement('input'),text=document.createElement('span');check.type='checkbox';check.checked=filterDraft.selected.has(v);text.textContent=v||'(Vacío)';check.onchange=()=>{if(check.checked)filterDraft.selected.add(v);else filterDraft.selected.delete(v);updateChoiceCount()};label.append(check,text);list.append(label)}if(!options.length){const empty=document.createElement('p');empty.textContent='No hay opciones con esa búsqueda.';list.append(empty)}updateChoiceCount()}
function updateChoiceCount(){const shown=visibleOptions(),n=shown.filter(v=>filterDraft.selected.has(v)).length,all=$('column-filter-all');all.checked=!!shown.length&&n===shown.length;all.indeterminate=n>0&&n<shown.length;all.disabled=!shown.length;$('column-filter-count').textContent=filterDraft.selected.size+' de '+filterCatalog.length+' valores seleccionados';}
function openColumnFilter(i){if(editingColumn!==null)closeColumnFilter();const f=columnFilters.get(i);editingColumn=i;filterAnchor=f.summary;filterCatalog=columnOptions(i);filterDraft=copyFilter(f);if(!f.enabled)filterDraft.selected=new Set(filterCatalog);$('column-filter-title').textContent='Filtrar por '+filterLabels[i];$('column-filter-search').value='';const modes=$('column-filter-mode');modes.replaceChildren();modes.hidden=i!==1;if(i===1){for(const [value,text] of [['','Todos'],['with','Con OT'],['without','Sin OT']]){const label=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name='column-ot-mode';radio.value=value;radio.checked=filterDraft.mode===value;radio.onchange=()=>filterDraft.mode=value;label.append(radio,document.createTextNode(text));modes.append(label)}}filterPanel.hidden=false;filterAnchor.setAttribute('aria-expanded','true');paintColumnChoices();positionColumnFilter();$('column-filter-search').focus({preventScroll:true})}
function refreshFilterChips(){filterChips.replaceChildren();columnFilters.forEach((f,i)=>{const active=f.enabled||!!f.mode;f.summary.classList.toggle('active',active);if(!active)return;const button=document.createElement('button');button.type='button';const mode=f.mode==='without'?'Sin OT':f.mode==='with'?'Con OT':'';const chosen=f.enabled?(f.selected.size===1?([...f.selected][0]||'(Vacío)'):f.selected.size+' valores'):'';button.textContent=filterLabels[i]+': '+[mode,chosen].filter(Boolean).join(' · ')+' ×';button.setAttribute('aria-label','Quitar filtro de '+filterLabels[i]);button.onclick=()=>{f.enabled=false;f.mode='';f.selected.clear();if(editingColumn===i)closeColumnFilter();refreshFilterChips();render()};filterChips.append(button)})}
headers.forEach((th,i)=>{th.textContent='';const button=document.createElement('button');button.type='button';button.className='column-filter-trigger';button.textContent=filterLabels[i]+' ▾';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.onclick=()=>{if(editingColumn===i)closeColumnFilter();else openColumnFilter(i)};th.append(button);columnFilters.set(i,{enabled:false,selected:new Set(),mode:'',summary:button})});
function refreshColumnOptions(){if(editingColumn!==null)closeColumnFilter();refreshFilterChips()}
$('column-filter-search').oninput=paintColumnChoices;
$('column-filter-all').onchange=()=>{for(const v of visibleOptions())if($('column-filter-all').checked)filterDraft.selected.add(v);else filterDraft.selected.delete(v);paintColumnChoices()};
$('column-filter-apply').onclick=()=>{if(editingColumn===null)return;const f=columnFilters.get(editingColumn);f.selected=new Set(filterDraft.selected);f.enabled=filterCatalog.length>0&&filterDraft.selected.size!==filterCatalog.length;f.mode=filterDraft.mode;closeColumnFilter();refreshFilterChips();render()};
$('column-filter-clear').onclick=()=>{if(editingColumn===null)return;const f=columnFilters.get(editingColumn);f.enabled=false;f.selected.clear();f.mode='';closeColumnFilter();refreshFilterChips();render()};
$('column-filter-cancel').onclick=$('column-filter-close').onclick=closeColumnFilter;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!filterPanel.hidden){e.preventDefault();closeColumnFilter()}});
document.addEventListener('pointerdown',e=>{if(!filterPanel.hidden&&!filterPanel.contains(e.target)&&!headers.some(h=>h.contains(e.target)))closeColumnFilter()});
window.addEventListener('resize',positionColumnFilter);window.addEventListener('scroll',e=>{if(!filterPanel.hidden&&!filterPanel.contains(e.target))positionColumnFilter()},true);

const progress=$('load-progress');let busy=false;
progress.addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('load-close').onclick=()=>progress.close();
function stage(label,n){$('load-stage').textContent=label;$('load-bar').value=n}
const paint=()=>new Promise(resolve=>setTimeout(resolve,0));

// Same day/week/month/year selection model as Planta Externa; colors remain by failure.
const cal=document.createElement('dialog');cal.className='calendar od-calendar';cal.innerHTML='<div class="dialogtop"><h2>Calendario</h2><button type="button" id="cal-close" aria-label="Cerrar calendario">×</button></div><div class="actions"><button type="button" id="cal-prev" aria-label="Periodo anterior">‹</button><button type="button" id="cal-title" style="flex:1"></button><button type="button" id="cal-next" aria-label="Periodo siguiente">›</button></div><div id="cal-grid" class="calgrid"></div><p id="cal-count" class="hint"></p><div class="actions cal-actions"><button type="button" id="cal-month">Mes completo</button><button type="button" id="cal-all">Limpiar selección</button><button type="button" class="primary" id="cal-ok">OK</button></div>';document.body.append(cal);
let calendarLevel='days',monthTimer=null,monthAction=null;
const calendarMonths=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
function validCalendarDay(key){if(!/^\d{4}-\d{2}-\d{2}$/.test(key))return false;const date=new Date(key+'T12:00:00Z');return !Number.isNaN(date.getTime())&&date.toISOString().slice(0,10)===key}
function available(){return new Set(data.map(r=>String(r.start||'').slice(0,10)).filter(validCalendarDay))}
function calendarISO(y,m,d){return new Date(Date.UTC(y,m,d,12)).toISOString().slice(0,10)}
function weekDays(key){const d=new Date(key+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return Array.from({length:7},(_,i)=>calendarISO(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()+i))}
function monthKeys(y=year,m=month){const prefix=calendarISO(y,m,1).slice(0,7);return [...available()].filter(s=>s.startsWith(prefix))}
function toggle(keys,force){const remove=force===undefined?keys.every(k=>draft.has(k)):!force;keys.forEach(k=>remove?draft.delete(k):draft.add(k));paintCal()}
function paintCal(){const allowed=available(),grid=$('cal-grid');grid.replaceChildren();grid.classList.toggle('caltiles',calendarLevel!=='days');$('cal-title').textContent=calendarLevel==='days'?calendarMonths[month]+' '+year+' ⌃':calendarLevel==='months'?year+' ⌃':'Años ⌃';$('cal-month').disabled=calendarLevel!=='days'||!monthKeys().length;$('cal-prev').disabled=$('cal-next').disabled=calendarLevel==='years';
function button(text,keys,action){const b=document.createElement('button');b.type='button';b.textContent=text;b.disabled=!keys.length;b.classList.toggle('selected',!!keys.length&&keys.every(k=>draft.has(k)));b.classList.toggle('partial',keys.some(k=>draft.has(k))&&!keys.every(k=>draft.has(k)));b.onclick=action;return b}
if(calendarLevel==='years'){for(const y of [...new Set([...allowed].map(d=>+d.slice(0,4)))].sort((a,b)=>a-b)){grid.append(button(String(y),[...allowed].filter(k=>k.startsWith(y+'-')),()=>{year=y;calendarLevel='months';paintCal()}))}if(!allowed.size){const empty=document.createElement('p');empty.textContent='No hay fechas de inicio disponibles.';grid.append(empty)}}else if(calendarLevel==='months'){calendarMonths.forEach((name,m)=>{const keys=monthKeys(year,m),b=button(name.slice(0,3),keys,()=>{if(monthTimer)clearTimeout(monthTimer);monthAction=()=>toggle(keys);monthTimer=setTimeout(()=>{monthTimer=null;const action=monthAction;monthAction=null;if(action)action()},260)});b.ondblclick=()=>{if(monthTimer)clearTimeout(monthTimer);monthTimer=null;monthAction=null;month=m;calendarLevel='days';paintCal()};b.title='Clic: seleccionar mes. Doble clic: abrir días.';grid.append(b)})}else{['Sem.','L','M','M','J','V','S','D'].forEach(t=>{const e=document.createElement('span');e.textContent=t;grid.append(e)});const first=weekDays(calendarISO(year,month,1))[0],last=calendarISO(year,month+1,0);for(let cursor=first;cursor<=last;){const week=weekDays(cursor),keys=week.filter(k=>allowed.has(k)),label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.disabled=!keys.length;check.checked=!!keys.length&&keys.every(k=>draft.has(k));check.indeterminate=keys.some(k=>draft.has(k))&&!check.checked;check.setAttribute('aria-label','Seleccionar semana del '+week[0]+' al '+week[6]);check.onchange=()=>toggle(keys,check.checked);label.className='cal-week';label.append(check);grid.append(label);for(const key of week){if(key.slice(0,7)!==calendarISO(year,month,1).slice(0,7)){grid.append(document.createElement('span'));continue}grid.append(button(String(+key.slice(8)),allowed.has(key)?[key]:[],()=>toggle([key])))}const d=new Date(cursor+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+7);cursor=d.toISOString().slice(0,10)}}$('cal-count').textContent=draft.size?draft.size+' días seleccionados. Pulsa OK para aplicar.':'Selecciona días, semanas o meses. Limpiar selección + OK muestra todos.'}
function cancelCalendar(){if(monthTimer)clearTimeout(monthTimer);monthTimer=null;monthAction=null;cal.close()}
$('calendar-open').onclick=()=>{const av=[...available()].sort();draft=new Set(dates||[]);calendarLevel='days';const today=new Date();year=today.getFullYear();month=today.getMonth();if(!monthKeys().length&&av.length){const latest=av.at(-1);year=+latest.slice(0,4);month=+latest.slice(5,7)-1}paintCal();cal.showModal()};$('cal-close').onclick=cancelCalendar;cal.addEventListener('cancel',()=>{if(monthTimer)clearTimeout(monthTimer);monthTimer=null;monthAction=null});$('cal-title').onclick=()=>{calendarLevel=calendarLevel==='days'?'months':calendarLevel==='months'?'years':'years';paintCal()};function shiftCalendar(n){if(calendarLevel==='years')return;const d=new Date(Date.UTC(year,month+(calendarLevel==='days'?n:n*12),1));year=d.getUTCFullYear();month=d.getUTCMonth();paintCal()}$('cal-prev').onclick=()=>shiftCalendar(-1);$('cal-next').onclick=()=>shiftCalendar(1);$('cal-month').onclick=()=>toggle(monthKeys(),true);$('cal-all').onclick=()=>{draft.clear();paintCal()};$('cal-ok').onclick=()=>{if(monthTimer){clearTimeout(monthTimer);monthTimer=null;const action=monthAction;monthAction=null;if(action)action()}dates=draft.size?new Set(draft):null;$('calendar-open').textContent=dates?'Calendario · '+dates.size+' días':'Calendario';cancelCalendar();render()};

// Coverage rendering, persistent import and map search, exclusive to Operación diaria.
const geo=window.odGeo;let searchLayer=null,coverageBusy=false;window.odResetMapSearch=()=>{if(searchLayer)searchLayer.clearLayers();$('map-search-status').textContent=''};
function coverageOpacity(){const value=state.preferences?.coverageOpacity;return typeof value==='number'&&Number.isFinite(value)?Math.max(.1,Math.min(.7,value)):.3}
function syncIntensity(){const value=Math.round(coverageOpacity()*100);$('coverage-intensity').hidden=!coverageOn;$('coverage-opacity').value=String(value);$('coverage-opacity-value').textContent=value+' %'}
$('coverage-opacity').oninput=()=>{const value=Math.max(10,Math.min(70,Number($('coverage-opacity').value)||30))/100;state.preferences={...state.preferences,coverageOpacity:value};$('coverage-opacity-value').textContent=Math.round(value*100)+' %';if(coverageLayer)coverageLayer.eachLayer(layer=>layer.setStyle({fillOpacity:value}))};$('coverage-opacity').onchange=()=>{if(ready)safelySave()};
function showCoverageNames(e){if(!coverageOn)return;const names=geo.namesAt([e.latlng.lat,e.latlng.lng],state.coverage);if(names.length)L.popup().setLatLng(e.latlng).setContent('<b>'+ (names.length===1?'Cobertura':'Coberturas en este punto')+'</b><br>'+names.map(esc).join('<br>')).openOn(map)}
function coverageStatus(){syncIntensity();const names=[...new Set(state.coverage.map(p=>p.name))].sort();$('coverage-toggle').disabled=!names.length||!ready||coverageBusy;$('coverage-toggle').classList.toggle('coverage-active',coverageOn);$('coverage-toggle').setAttribute('aria-pressed',String(coverageOn));$('coverage-toggle').title=coverageOn?'Ocultar polígonos de cobertura':'Mostrar polígonos de cobertura';$('coverage-info').textContent=names.length?state.coverage.length+' polígonos guardados · '+names.length+' clústeres · '+(coverageOn?'visibles':'ocultos'):'Carga un archivo KMZ o KML para ver los polígonos de cobertura.';$('newcluster').replaceChildren(new Option(names.length?'Selecciona un clúster':'Carga primero el KMZ',''),...names.map(n=>new Option(n,n)))}
function drawCoverage(){if(!map)return;coverageLayer.clearLayers();const names=[...new Set(state.coverage.map(p=>p.name))].sort();state.coverage.forEach(p=>{const shape=L.polygon(p.rings,{pane:'od-coverage',color:colors[names.indexOf(p.name)%colors.length],weight:2,fillOpacity:coverageOpacity(),interactive:false});shape.addTo(coverageLayer)});if(coverageOn){if(!map.hasLayer(coverageLayer))coverageLayer.addTo(map)}else if(map.hasLayer(coverageLayer))map.removeLayer(coverageLayer);coverageStatus()}
const initialMapInit=mapInit;mapInit=function(){const before=map;initialMapInit();if(map&&!before){const pane=map.createPane('od-coverage');pane.style.zIndex=350;searchLayer=L.layerGroup().addTo(map);map.on('click',showCoverageNames);if(typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(()=>map.invalidateSize({pan:false}));observer.observe($('daily-map'))}drawCoverage()}};
function restoreCoverage(){state.coverage=geo.unique(Array.isArray(state.coverage)?state.coverage:[]);coverageStatus();if(map)drawCoverage()}
function setCoverage(on,fit){if(!map)return;coverageOn=!!on;if(coverageOn){if(!map.hasLayer(coverageLayer))coverageLayer.addTo(map);if(fit&&state.coverage.length){const bounds=L.latLngBounds(state.coverage.flatMap(p=>p.rings[0]));map.invalidateSize();map.fitBounds(bounds,{padding:[24,24],maxZoom:15})}}else if(map.hasLayer(coverageLayer))map.removeLayer(coverageLayer);coverageStatus()}
$('coverage-toggle').onclick=()=>{if(!state.coverage.length||coverageBusy)return;tab(true);if(!map)return toast('No se pudo abrir el mapa. Revisa internet.');setCoverage(!coverageOn,!coverageOn)};
$('coverage-view').onclick=()=>{$('coverage-toggle').click()};
// Use an independent progress window so Excel import is unaffected.
const coverageProgress=document.createElement('dialog');coverageProgress.id='coverage-progress';coverageProgress.innerHTML='<h2 id="coverage-progress-title">Cargando cobertura</h2><p id="coverage-progress-stage" role="status" aria-live="polite"></p><progress id="coverage-progress-bar" max="4" value="0"></progress><div id="coverage-progress-summary"></div><button type="button" id="coverage-progress-close" hidden>Cerrar</button>';document.body.append(coverageProgress);coverageProgress.addEventListener('cancel',e=>{if(coverageBusy)e.preventDefault()});$('coverage-progress-close').onclick=()=>coverageProgress.close();
function coverageStage(text,value){$('coverage-progress-stage').textContent=text;$('coverage-progress-bar').value=value}
function coverageLock(lock){coverageBusy=lock;['coverage-load','load-records','new','delete-records'].forEach(n=>$(n).disabled=lock||!ready);coverageStatus()}
$('coverage-load').onclick=()=>{if(ready&&!coverageBusy)$('coverage-file').click()};
$('coverage-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const previous=state.coverage;let stored=false;try{coverageLock(true);$('coverage-progress-title').textContent='Cargando cobertura';$('coverage-progress-close').hidden=true;$('coverage-progress-summary').textContent='';coverageStage('Leyendo archivo…',0);coverageProgress.showModal();await paint();if(!/\.(kmz|kml)$/i.test(f.name))throw Error('Selecciona un archivo con extensión .kmz o .kml.');let documents=[];if(/\.kmz$/i.test(f.name)){if(!window.JSZip)throw Error('No se pudo cargar el lector de KMZ. Revisa la conexión a internet.');coverageStage('Descomprimiendo KMZ…',1);await paint();const zip=await JSZip.loadAsync(await f.arrayBuffer());const entries=Object.values(zip.files).filter(x=>!x.dir&&/\.kml$/i.test(x.name));if(!entries.length)throw Error('El KMZ no contiene archivos KML.');for(const entry of entries)documents.push(await entry.async('string'))}else documents=[await f.text()];coverageStage('Extrayendo geometrías…',2);await paint();let found=[],invalid=0;for(const xml of documents){const extracted=geo.extractKML(xml);found.push(...extracted.polygons);invalid+=extracted.invalid}if(!found.length)throw Error('No se encontraron polígonos válidos con nombre. La cobertura anterior se conserva.');const result=geo.merge(previous,found);coverageStage('Guardando cobertura en este navegador…',3);await paint();state.coverage=result.polygons;await save();stored=true;coverageStage('Cobertura cargada y guardada.',4);$('coverage-progress-title').textContent='Carga completada';$('coverage-progress-summary').innerHTML='<p>'+esc(f.name)+'</p><p>'+result.added+' polígonos nuevos · '+result.updated+' actualizados · '+result.repeated+' sin cambios.</p><p>'+result.duplicates+' duplicados del archivo omitidos · '+invalid+' geometrías inválidas omitidas.</p><p><strong>'+state.coverage.length+' polígonos en total.</strong></p><p class="hint">La cobertura se conserva al volver a abrir este módulo en el mismo navegador y dirección.</p>';restoreCoverage();tab(true);if(map)setCoverage(true,true);else toast('La cobertura está guardada, pero no se pudo abrir el mapa. Revisa internet.');}catch(err){if(!stored)state.coverage=previous;$('coverage-progress-title').textContent=stored?'Cobertura guardada; revisar visualización':'No se completó la carga';coverageStage(err.message||'Error al cargar la cobertura.',stored?4:0);restoreCoverage()}finally{coverageLock(false);$('coverage-progress-close').hidden=false;e.target.value=''}};
function markerDescription(r){return '<b>'+esc(r.folio||r.ot||r.os)+'</b><br>OT: '+esc(r.ot||'Sin OT')+'<br>OS: '+esc(r.os||'Sin OS')+'<br>Clúster: '+esc(r.cluster||'Sin clúster')+'<br>Falla: '+esc(r.failure||'')}
function runMapSearch(){const q=$('search').value.trim();if(!q){if(searchLayer)searchLayer.clearLayers();$('map-search-status').textContent='';return}const point=geo.coordinate(q);if(!point&&/[,;]/.test(q)){$('map-search-status').textContent='Coordenadas inválidas. Usa latitud, longitud; por ejemplo: 20.6284, -103.4362.';return}const matches=point?[]:visible.filter(r=>[r.ot,r.os].some(v=>String(v||'').toLocaleLowerCase().includes(q.toLocaleLowerCase())));if(!point&&!matches.length){$('map-search-status').textContent='No hay registros con esa OT u OS dentro de los filtros activos.';if(searchLayer)searchLayer.clearLayers();return}tab(true);if(!map){$('map-search-status').textContent='No se pudo abrir el mapa. Revisa la conexión a internet.';return}searchLayer.clearLayers();if(point){if(state.coverage.length)setCoverage(true,false);const names=geo.namesAt(point,state.coverage),near=visible.filter(r=>{const c=geo.coordinate(r.coords);return c&&Math.abs(c[0]-point[0])<.00001&&Math.abs(c[1]-point[1])<.00001});const label=state.coverage.length?(names.length?'Cobertura: '+names.map(esc).join(', '):'Fuera de los polígonos de cobertura cargados.'):'Sin cobertura cargada para identificar el clúster.';L.circleMarker(point,{radius:12,color:'#fff',weight:3,fillColor:'#007f89',fillOpacity:1,bubblingMouseEvents:false}).bindPopup('<b>Coordenadas consultadas</b><br>'+esc(point.join(', '))+'<br>'+label+(near.length?'<br>'+near.length+' registros coincidentes.':'')).addTo(searchLayer).openPopup();map.setView(point,18);$('map-search-status').textContent=(names.length?'Cobertura: '+names.join(', '):state.coverage.length?'Punto fuera de la cobertura cargada.':'Punto localizado. Carga cobertura para identificar el clúster.')+(near.length?' · '+near.length+' registros coincidentes.':'');}else{const located=matches.map(r=>({r,c:geo.coordinate(r.coords)})).filter(x=>x.c);if(!located.length){$('map-search-status').textContent=matches.length+' registros encontrados, sin coordenadas del cierre válidas. No se puede ubicarlos en el mapa.';return}let only;for(const {r,c} of located)only=L.circleMarker(c,{radius:12,color:'#fff',weight:3,fillColor:'#007f89',fillOpacity:1,bubblingMouseEvents:false}).bindPopup(markerDescription(r)).addTo(searchLayer);if(located.length===1){map.setView(located[0].c,18);only.openPopup()}else map.fitBounds(L.latLngBounds(located.map(x=>x.c)),{padding:[30,30],maxZoom:18});$('map-search-status').textContent=matches.length+' registros encontrados · '+located.length+' ubicados en el mapa'+(matches.length>located.length?' · '+(matches.length-located.length)+' sin coordenadas válidas':'')+'.'}setTimeout(()=>map.invalidateSize(),50)}
$('map-search-go').onclick=runMapSearch;$('search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runMapSearch()}});$('search-x').onclick=()=>{$('search').value='';if(searchLayer)searchLayer.clearLayers();$('map-search-status').textContent='';render();$('search').focus()};

function assignMissing(){data.forEach(r=>{if(!r.folio)r.folio=folio(r)});render()}
$('new').onclick=()=>{if(!ready)return;restoreCoverage();$('formdialog').showModal()};$('form').onsubmit=async e=>{e.preventDefault();if(!ready)return;let r=Object.fromEntries(new FormData(e.target));if(!String(r.ot||'').trim()&&!String(r.os||'').trim())return toast('Indica al menos una OT o una OS.');if(r.end&&r.end<r.start)return toast('El término debe ser posterior al inicio.');if(!noOT(r)&&data.some(x=>x.ot===r.ot))return toast('Ya existe esa OT. Revisa el registro antes de crear otro.');r.origin='manual';r.id=id();r.folio=folio(r);data.unshift(r);await safelySave();e.target.reset();subtype();$('formdialog').close();statuses();$('data-origin').textContent=origin();render()};
$('delete-records').onclick=async()=>{const n=data.filter(r=>r.origin==='import').length;if(!n)return toast('No hay registros importados para borrar.');if(!confirm('¿Borrar los '+n+' registros importados y sus pausas históricas? Se conservarán las detenciones manuales y las coberturas.'))return;const kept=data.filter(r=>r.origin!=='import');data.splice(0,data.length,...kept);state.pauses=[];dates=null;await safelySave();sync();toast('Registros importados borrados. Las coberturas se conservaron.')};
const file=$('records-file'),dialog=$('import-dialog');$('load-records').onclick=()=>{if(ready)file.click()};file.onchange=async()=>{const f=file.files[0];if(!f)return;try{busy=true;$('load-title').textContent='Cargando archivo';$('load-close').hidden=true;$('load-summary').textContent='';stage('Leyendo '+f.name+'…',0);progress.showModal();await paint();if(!window.XLSX)throw Error('No se pudo cargar el lector de Excel. Revisa internet.');const buffer=await f.arrayBuffer();stage('Validando registros…',1);await paint();const wb=XLSX.read(buffer,{type:'array',cellDates:true});pending=window.odParse(wb.SheetNames.map(name=>({name,rows:XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:null,raw:true})})));busy=false;progress.close();$('import-report').innerHTML='<p>'+esc(f.name)+'</p><p>'+pending.records.length+' registros preparados · '+pending.records.filter(noOT).length+' sin OT.</p><p>'+pending.identical+' duplicados idénticos omitidos. '+pending.skipped.length+' filas omitidas por falta de datos.</p><p class="hint">'+pending.skipped.map(x=>'Fila '+x.row+': '+esc(x.reason)).join('<br>')+'</p>';dialog.showModal()}catch(e){busy=false;$('load-title').textContent='No se completó la carga';stage(e.message,0);$('load-close').hidden=false}finally{file.value=''}};$('import-cancel').onclick=()=>{pending=null;dialog.close()};
$('import-confirm').onclick=async()=>{if(!pending||!ready)return;const batch=pending;dialog.close();busy=true;$('load-close').hidden=true;$('load-title').textContent='Guardando registros';stage('Guardando en este navegador…',2);progress.showModal();await paint();const before=structuredClone(state),oldData=[...data];try{const previous=data.filter(r=>r.origin==='import'),manual=data.filter(r=>r.origin==='manual'),used=new Set();const imported=batch.records.map(r=>{const key=JSON.stringify(r.raw),existing=previous.find(x=>!used.has(x.id)&&JSON.stringify(x.raw)===key);if(existing){used.add(existing.id);return existing}return {...r,id:id(),origin:'import',folio:folio(r)}});data.splice(0,data.length,...manual,...imported);state.pauses=batch.pauses;await save();pending=null;dates=null;$('calendar-open').textContent='Calendario';$('search').value='';$('status').value='';columnFilters.forEach(f=>{f.enabled=false;f.selected.clear();f.mode='';f.summary.classList.toggle('active',false)});sync();stage('Carga completada y guardada.',3);$('load-title').textContent='Carga completada';$('load-summary').innerHTML='<p>Archivos procesados: <b>1</b></p><p>Registros cargados: <b>'+imported.length+'</b></p><p>Sin OT: <b>'+imported.filter(noOT).length+'</b></p><p>Total almacenado, incluidas capturas manuales: <b>'+data.length+'</b></p><p>Duplicados idénticos omitidos: '+batch.identical+'</p><p>Filas omitidas: '+batch.skipped.length+'</p>';}catch(e){state=before;data.splice(0,data.length,...oldData);sync();$('load-title').textContent='No se guardó la carga';stage(e.message,0);}finally{busy=false;$('load-close').hidden=false}};
// Opening and persistence use a dedicated database, without reading other modules.
['new','load-records','delete-records','coverage-load'].forEach(n=>$(n).disabled=true);
try{const req=indexedDB.open('primavera_operacion_diaria',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onerror=()=>fail(req.error);req.onsuccess=()=>{db=req.result;const tx=db.transaction('state','readonly'),get=tx.objectStore('state').get('current');get.onsuccess=()=>{if(get.result)state=get.result;ready=true;['new','load-records','delete-records','coverage-load'].forEach(n=>$(n).disabled=false);sync();restoreCoverage();$('storage-note').textContent='Datos locales de este navegador. Soporte, Repeat 60 y Planta Externa son independientes.'};get.onerror=()=>fail(get.error)}}catch(e){fail(e)}function fail(e){$('storage-note').textContent='No se pudo abrir el almacenamiento: '+(e?.message||'acceso bloqueado');toast('El navegador debe permitir el almacenamiento para trabajar con registros.');}
render();
})();
